import { Component, OnInit } from '@angular/core';
import { Router, NavigationEnd } from '@angular/router';
import { HealthService } from '../../services/health.service';
import { AuthService } from '../../services/auth.service';
import { HealthData } from '../../models/health-data.model';
import { filter } from 'rxjs/operators';

@Component({
  selector: 'app-home',
  templateUrl: './home.component.html',
  styleUrls: ['./home.component.scss']
})
export class HomeComponent implements OnInit {
  testToken: string = '';
  isGeneratingToken = false;
  userEmail: string = '';
  healthData: HealthData[] = [];
  latestUpload: HealthData | null = null;
  isLoading = false;

  constructor(
    private router: Router,
    private healthService: HealthService,
    private authService: AuthService
  ) { }

  ngOnInit(): void {
    // Get user email from token if available
    this.userEmail = this.authService.getUserEmail() || '';

    // Load health data if user is authenticated
    if (this.authService.isAuthenticated()) {
      this.loadHealthData();
    }

    // Listen for navigation events to refresh data when returning from upload
    this.router.events
      .pipe(filter(event => event instanceof NavigationEnd))
      .subscribe((event) => {
        const navEnd = event as NavigationEnd;
        console.log('Home: Navigation detected:', navEnd.url);
        // If navigating back to home page, refresh data
        if (navEnd.url === '/' && this.authService.isAuthenticated()) {
          console.log('Home: Refreshing data due to navigation');
          this.loadHealthData();
        }
      });
  }

  goToUpload(): void {
    this.router.navigate(['/upload']);
  }

  goToDashboard(): void {
    this.router.navigate(['/dashboard']);
  }

  generateTestToken(): void {
    this.isGeneratingToken = true;
    this.healthService.generateTestToken().subscribe({
      next: (response) => {
        this.testToken = response.token;
        // Store token using AuthService
        this.authService.setToken(response.token);

        // Update user email display
        this.userEmail = this.authService.getUserEmail() || '';

        // Load health data after getting token
        this.loadHealthData();

        this.isGeneratingToken = false;
        console.log('Test Token:', response.token);
        console.log('Token stored for automatic authentication');
        console.log('User email:', this.userEmail);
      },
      error: (error) => {
        console.error('Error generating token:', error);
        this.isGeneratingToken = false;
      }
    });
  }

  loadHealthData(): void {
    this.isLoading = true;
    this.healthService.getHealthData().subscribe({
      next: (data: HealthData[]) => {
        console.log('Home: Loaded health data:', data);
        this.healthData = data;
        this.latestUpload = this.getLatestUpload(data);
        console.log('Home: Latest upload:', this.latestUpload);
        this.isLoading = false;
      },
      error: (error) => {
        console.error('Error loading health data:', error);
        this.isLoading = false;
      }
    });
  }

  getLatestUpload(data: HealthData[]): HealthData | null {
    if (data.length === 0) return null;
    // Sort by date first, then by ID (higher ID = more recent)
    const sortedData = [...data].sort((a, b) => {
      const dateCompare = new Date(b.date).getTime() - new Date(a.date).getTime();
      if (dateCompare !== 0) return dateCompare;
      return (b.id || 0) - (a.id || 0); // Higher ID = more recent
    });
    return sortedData[0];
  }

  convertCaloriesToKcal(calories: number | null): number {
    if (!calories) return 0;
    return calories / 1000;
  }

  formatCalories(calories: number | null): string {
    if (!calories) return '0';
    return calories.toLocaleString();
  }

  formatKcal(calories: number | null): string {
    if (!calories) return '0.00';
    return this.convertCaloriesToKcal(calories).toFixed(2);
  }
}
